const fs = require\("fs"\);
const path = require\("path"\);
const base = "stitch_hrm_pro_enterprise_suite/stitch_hrm_pro_enterprise_suite";
const pages = {
  conges: "mes_cong_s_hrm_pro_collaborateur",
  payslips: "mes_fiches_de_paie_hrm_pro_collaborateur",
  attendance: "mon_pointage_hrm_pro_collaborateur",
  documents: "mes_documents_profil_hrm_pro_collaborateur",
  dashboard: "tableau_de_bord_collaborateur_hrm_pro"
};
for \(const [key, dir] of Object.entries\(pages\)\) {
  const html = fs.readFileSync\(path.join\(base, dir, "code.html"\), "utf8"\);
  const m = html.match\(/<main[^>]*>\([\\s\\S]*?\)<\\/main>/\);
  if \(!m\) { console.log\(key, "NO MAIN"\); continue; }
  fs.writeFileSync\(`/tmp/hrm_extract/${key}.html`, m[1].trim\(\)\);
  const scripts = [...html.matchAll\(/<script\(?![^>]*src=\)[^>]*>\([\\s\\S]*?\)<\\/script>/g\)].map\(x => x[1]\);
  console.log\(key, "main chars:", m[1].length, "scripts:", scripts.length, "braces:", \(m[1].match\(/\\{\\{/g\)||[]\).length, "ats:", \(m[1].match\(/@[a-zA-Z]+/g\)||[]\).slice\(0,5\).join\(","\)\);
}
')

